16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "postcode")
48	    @Pattern(regexp = "^[0-9]{4}$", message = "Postcode must be 4 digits")
49	    private String postcode;
50	
51	    @Column(name = "telephone")
52	    @NotEmpty
53	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
54	    private String telephone;
55	
56	    @Column(name = "email")
57	    @Email
58	    private String email;
59	
60	    @Column(name = "registration_date")
61	    private LocalDate registrationDate;
62	
63	    @Column(name = "birth_date")
64	    private LocalDate birthDate;
65	
66	    @Column(name = "customer_code")
67	    private String customerCode;
68	
69	    @Column(name = "household_id")
70	    private String householdId;
71	
72	    @Column(name = "namesake_count")
73	    private Integer namesakeCount;
74	
75	    @Column(name = "bulk_signup_warning")
76	    private Boolean bulkSignupWarning;
77	
78	    @Column(name = "possible_duplicate")
79	    private Boolean possibleDuplicate;
80	
81	    @Column(name = "possible_duplicate_of")
82	    private Integer possibleDuplicateOf;
83	
84	    /**
85	     * Number of owners belonging to this owner's household (owners sharing the same
86	     * {@code householdId}), including this owner. Derived at request time rather than stored, and
87	     * used to award the {@code GOLD} membership tier to households of three or more members.
88	     */
89	    @Transient
90	    private Integer householdMemberCount;
91	
92	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
93	    private Set<Pet> pets;
94	
95	    public String getAddress() {
96	        return this.address;
97	    }
98	
99	    public void setAddress(String address) {
100	        this.address = address;
101	    }
102	
103	    public String getCity() {
104	        return this.city;
105	    }
106	
107	    public void setCity(String city) {
108	        this.city = city;
109	    }
110	
111	    public String getPostcode() {
112	        return this.postcode;
113	    }
114	
115	    public void setPostcode(String postcode) {
116	        this.postcode = postcode;
117	    }
118	
119	    public String getTelephone() {
120	        return this.telephone;
121	    }
122	
123	    public void setTelephone(String telephone) {
124	        this.telephone = telephone;
125	    }
126	
127	    public String getEmail() {
128	        return this.email;
129	    }
130	
131	    public void setEmail(String email) {
132	        this.email = email;
133	    }
134	
135	    public LocalDate getRegistrationDate() {
136	        return this.registrationDate;
137	    }
138	
139	    public void setRegistrationDate(LocalDate registrationDate) {
140	        this.registrationDate = registrationDate;
141	    }
142	
143	    public LocalDate getBirthDate() {
144	        return this.birthDate;
145	    }
146	
147	    public void setBirthDate(LocalDate birthDate) {
148	        this.birthDate = birthDate;
149	    }
150	
151	    public String getCustomerCode() {
152	        return this.customerCode;
153	    }
154	
155	    public void setCustomerCode(String customerCode) {
156	        this.customerCode = customerCode;
157	    }
158	
159	    public String getHouseholdId() {
160	        return this.householdId;
161	    }
162	
163	    public void setHouseholdId(String householdId) {
164	        this.householdId = householdId;
165	    }
166	
167	    public Integer getNamesakeCount() {
168	        return this.namesakeCount;
169	    }
170	
171	    public void setNamesakeCount(Integer namesakeCount) {
172	        this.namesakeCount = namesakeCount;
173	    }
174	
175	    public Boolean getBulkSignupWarning() {
176	        return this.bulkSignupWarning;
177	    }
178	
179	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
180	        this.bulkSignupWarning = bulkSignupWarning;
181	    }
182	
183	    public Boolean getPossibleDuplicate() {
184	        return this.possibleDuplicate;
185	    }
186	
187	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
188	        this.possibleDuplicate = possibleDuplicate;
189	    }
190	
191	    public Integer getPossibleDuplicateOf() {
192	        return this.possibleDuplicateOf;
193	    }
194	
195	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
196	        this.possibleDuplicateOf = possibleDuplicateOf;
197	    }
198	
199	    public Integer getHouseholdMemberCount() {
200	        return this.householdMemberCount;
201	    }
202	
203	    public void setHouseholdMemberCount(Integer householdMemberCount) {
204	        this.householdMemberCount = householdMemberCount;
205	    }
206	
207	    protected Set<Pet> getPetsInternal() {
208	        if (this.pets == null) {
209	            this.pets = new HashSet<>();
210	        }
211	        return this.pets;
212	    }
213	
214	    protected void setPetsInternal(Set<Pet> pets) {
215	        this.pets = pets;
216	    }
217	
218	    public List<Pet> getPets() {
219	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
220	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
221	        return Collections.unmodifiableList(sortedPets);
222	    }
223	
224	    public void setPets(List<Pet> pets) {
225	        this.pets = new HashSet<>(pets);
226	    }
227	
228	    public void addPet(Pet pet) {
229	        getPetsInternal().add(pet);
230	        pet.setOwner(this);
231	    }
232	
233	    /**
234	     * Return the Pet with the given name, or null if none found for this Owner.
235	     *
236	     * @param name to test
237	     * @return true if pet name is already in use
238	     */
239	    public Pet getPet(String name) {
240	        return getPet(name, false);
241	    }
242	
243	    /**
244	     * Return the Pet with the given name, or null if none found for this Owner.
245	     *
246	     * @param name to test
247	     * @return true if pet name is already in use
248	     */
249	    public Pet getPet(String name, boolean ignoreNew) {
250	        name = name.toLowerCase();
251	        for (Pet pet : getPetsInternal()) {
252	            if (!ignoreNew || !pet.isNew()) {
253	                String compName = pet.getName();
254	                compName = compName.toLowerCase();
255	                if (compName.equals(name)) {
256	                    return pet;
257	                }
258	            }
259	        }
260	        return null;
261	    }
262	
263	    public Pet getPet(Integer petId) {
264	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
265	    }
266	
267	    @Override
268	    public String toString() {
269	        return new ToStringCreator(this)
270	
271	            .append("id", this.getId())
272	            .append("new", this.isNew())
273	            .append("lastName", this.getLastName())
274	            .append("firstName", this.getFirstName())
275	            .append("address", this.address)
276	            .append("city", this.city)
277	            .append("postcode", this.postcode)
278	            .append("telephone", this.telephone)
279	            .toString();
280	    }
281	}
