32	import org.springframework.samples.petclinic.mapper.MembershipLevelResolver;
33	import org.springframework.samples.petclinic.mapper.OwnerMapper;
34	import org.springframework.samples.petclinic.mapper.PetMapper;
35	import org.springframework.samples.petclinic.mapper.Region;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
41	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
42	import org.springframework.samples.petclinic.rest.advice.FutureRegistrationDateException;
43	import org.springframework.samples.petclinic.rest.advice.InvalidPostcodeException;
44	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
45	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
46	import org.springframework.samples.petclinic.rest.api.OwnersApi;
47	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
48	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.PetDto;
50	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
51	import org.springframework.samples.petclinic.rest.dto.VisitDto;
52	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
53	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
54	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
55	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
56	import org.springframework.samples.petclinic.service.ClinicService;
57	import org.springframework.security.access.prepost.PreAuthorize;
58	import org.springframework.web.bind.annotation.CrossOrigin;
59	import org.springframework.web.bind.annotation.RequestMapping;
60	import org.springframework.web.bind.annotation.RestController;
61	import org.springframework.web.util.UriComponentsBuilder;
62	
63	import jakarta.transaction.Transactional;
64	
65	/**
66	 * @author Vitaliy Fedoriv
67	 */
68	
69	@RestController
70	@CrossOrigin(exposedHeaders = "errors, content-type")
71	@RequestMapping("/api")
72	public class OwnerRestControllerV1 implements OwnersApi {
73	
74	    /** Dedicated audit logger; a successful create emits a single line here with the new owner's key details. */
75	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
76	
77	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
78	    private static final int MAX_OWNERS_PER_CITY = 50;
79	
80	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
81	    private static final int MAX_OWNERS_PER_DAY = 100;
82	
83	    /** Once more than this many owners already exist for a day, a further create for that day is flagged as a bulk signup. */
84	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
85	
86	    private final ClinicService clinicService;
87	
88	    private final OwnerMapper ownerMapper;
89	
90	    private final PetMapper petMapper;
91	
92	    private final VisitMapper visitMapper;
93	
94	    private final TelephoneNormalizer telephoneNormalizer;
95	
96	    private final AddressNormalizer addressNormalizer;
97	
98	    private final EmailNormalizer emailNormalizer;
99	
100	    private final IdentityKeyResolver identityKeyResolver;
101	
102	    private final HouseholdResolver householdResolver;
103	
104	    public OwnerRestControllerV1(ClinicService clinicService,
105	                                 OwnerMapper ownerMapper,
106	                                 PetMapper petMapper,
107	                                 VisitMapper visitMapper,
108	                                 TelephoneNormalizer telephoneNormalizer,
109	                                 AddressNormalizer addressNormalizer,
110	                                 EmailNormalizer emailNormalizer,
111	                                 IdentityKeyResolver identityKeyResolver,
112	                                 HouseholdResolver householdResolver) {
113	        this.clinicService = clinicService;
114	        this.ownerMapper = ownerMapper;
115	        this.petMapper = petMapper;
116	        this.visitMapper = visitMapper;
117	        this.telephoneNormalizer = telephoneNormalizer;
118	        this.addressNormalizer = addressNormalizer;
119	        this.emailNormalizer = emailNormalizer;
120	        this.identityKeyResolver = identityKeyResolver;
121	        this.householdResolver = householdResolver;
122	    }
123	
124	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
125	    @Override
126	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
127	        Collection<Owner> owners;
128	        if (lastName != null) {
129	            owners = this.clinicService.findOwnerByLastName(lastName);
130	        } else {
131	            owners = this.clinicService.findAllOwners();
132	        }
133	        if (owners.isEmpty()) {
134	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
135	        }
136	        owners.forEach(this::populateHouseholdMemberCount);
137	        List<OwnerDto> ownerDtos = owners.stream().map(this::toOwnerDto).toList();
138	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
144	        Owner owner = this.clinicService.findOwnerById(ownerId);
145	        if (owner == null) {
146	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
147	        }
148	        populateHouseholdMemberCount(owner);
149	        return new ResponseEntity<>(toOwnerDto(owner), HttpStatus.OK);
150	    }
151	
152	    /**
153	     * Maps an owner to its DTO and stamps on the derived {@code identityKey} (see
154	     * {@link IdentityKeyResolver#deriveIdentityKey}), which is not a stored field of the owner and so cannot be produced
155	     * by the mapper alone.
156	     *
157	     * @param owner the owner to map
158	     * @return the owner DTO carrying its identity key
159	     */
160	    private OwnerDto toOwnerDto(Owner owner) {
161	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
162	        ownerDto.setIdentityKey(identityKeyResolver.deriveIdentityKey(owner));
163	        return ownerDto;
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Transactional
168	    @Override
169	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
170	        normalizeAndValidate(ownerFieldsDto);
171	        HttpHeaders headers = new HttpHeaders();
172	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
173	        populateDerivedFields(owner, ownerFieldsDto);
174	        requireUniqueIdentity(owner);
175	        requireHouseholdNotDuplicate(owner, ownerFieldsDto);
176	        flagPossibleDuplicate(owner, ownerFieldsDto);
177	        this.clinicService.saveOwner(owner);
178	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
179	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
180	            MembershipLevelResolver.deriveMembershipLevel(owner.getEmail(), owner.getNamesakeCount()));
181	        populateHouseholdMemberCount(owner);
182	        OwnerDto ownerDto = toOwnerDto(owner);
183	        headers.setLocation(UriComponentsBuilder.newInstance()
184	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
185	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
186	    }
187	
188	    /**
189	     * Stamps onto a newly mapped owner every field derived at creation from the owner itself and from the owners that
190	     * already exist, in the order each field depends on. The {@code customerCode} is derived from the owner's own
191	     * fields (see {@link IdentityKeyResolver#deriveCustomerCode}); the {@code namesakeCount} (see
192	     * {@link #countNamesakes}) and {@code bulkSignupWarning} (see {@link #computeBulkSignupWarning}) are snapshots of
193	     * the existing owners taken before this owner is saved, so neither counts the new owner itself; and the shared
194	     * {@code householdId} is assigned last (see {@link #assignHouseholdId}), derived deterministically from the owner's
195	     * last name and postcode, so it is in place before {@link #requireUniqueIdentity} derives the identity key. The
196	     * owner is mutated in place; the caller applies the duplicate guards and saves it.
197	     *
198	     * @param owner          the newly mapped owner about to be saved
199	     * @param ownerFieldsDto the incoming owner payload
200	     */
201	    private void populateDerivedFields(Owner owner, OwnerFieldsDto ownerFieldsDto) {
202	        owner.setCustomerCode(identityKeyResolver.deriveCustomerCode(owner));
203	        owner.setNamesakeCount(countNamesakes(owner));
204	        owner.setBulkSignupWarning(computeBulkSignupWarning(owner.getRegistrationDate()));
205	        assignHouseholdId(owner);
206	    }
207	
208	    /**
209	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
210	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
211	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
212	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
213	     * it; the email is canonicalized; and the registration date is resolved to its effective business day. The
214	     * effective registration date is the supplied value or, when none was supplied, the current server date; when it
215	     * falls on a weekend it is rolled forward to the following Monday and that adjusted date is written back onto the
216	     * payload, so every value derived from it (such as the membership number's year segment and the per-day limit)
217	     * uses the adjusted date. The payload is mutated in place so the caller can map and save it directly. Duplicate
218	     * detection is deferred: it runs once, against the derived {@code identityKey}, after the household id has been
219	     * assigned (see {@link #requireUniqueIdentity}).
220	     *
221	     * @param ownerFieldsDto the incoming owner payload, mutated in place
222	     * @throws MissingOwnerFieldsException if any required field is missing or blank
223	     */
224	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
225	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
226	        validateRequiredFields(ownerFieldsDto);
227	        validatePostcode(ownerFieldsDto);
228	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
229	        ownerFieldsDto.setTelephone(telephone);
230	        requireCityHasCapacity(ownerFieldsDto.getCity());
231	        LocalDate registrationDate = resolveRegistrationDate(ownerFieldsDto);
232	        ownerFieldsDto.setRegistrationDate(registrationDate);
233	        requireDailyLimitNotReached(registrationDate);
234	        normalizeEmail(ownerFieldsDto);
235	    }
236	
237	    /**
238	     * Normalizes an owner's optional email to its canonical stored form and writes it back onto the payload. The
239	     * canonical form (see {@link EmailNormalizer#normalize}) is what gets stored and returned as {@code email} and what
240	     * every email comparison uses; a missing (blank or {@code null}) email is left untouched. The payload is mutated in
241	     * place so the caller can map and save it directly.
242	     *
243	     * @param ownerFieldsDto the incoming owner payload, mutated in place
244	     */
245	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
246	        ownerFieldsDto.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
247	    }
248	
249	    /**
250	     * Resolves an owner's effective registration date and rolls it onto a business day. The effective date is the value
251	     * supplied on the payload, or the current server date when none was supplied; when that date is a Saturday or
252	     * Sunday it is rolled forward to the following Monday. The returned date is always a business day. A supplied date
253	     * later than the current server date is rejected.
254	     *
255	     * @param ownerFieldsDto the incoming owner payload
256	     * @return the effective registration date rolled forward onto a business day
257	     * @throws FutureRegistrationDateException if a supplied registration date is later than the current server date
258	     */
259	    private LocalDate resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
260	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
261	        if (effective == null) {
262	            effective = LocalDate.now();
263	        }
264	        else if (effective.isAfter(LocalDate.now())) {
265	            throw new FutureRegistrationDateException(
266	                "the registration date must not be later than the current server date");
267	        }
268	        while (effective.getDayOfWeek() == DayOfWeek.SATURDAY || effective.getDayOfWeek() == DayOfWeek.SUNDAY) {
269	            effective = effective.plusDays(1);
270	        }
271	        return effective;
272	    }
273	
274	    /**
275	     * Rejects creating an owner once the maximum number of owners for the adjusted business day has already been
276	     * reached. The cap is 100, so when 100 or more existing owners carry the given adjusted {@code registrationDate} no
277	     * further owner may be created for that day.
278	     *
279	     * @param registrationDate the adjusted business-day registration date of the owner being created
280	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created for that day
281	     */
282	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
283	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
284	            throw new DailyOwnerLimitExceededException(
285	                "the maximum number of owners for today has already been reached");
286	        }
287	    }
288	
289	    /**
290	     * Counts how many existing owners already carry the given adjusted business-day {@code registrationDate}. Invoked
291	     * before the new owner is saved, so the count reflects only owners that predate this create. Shared by
292	     * {@link #requireDailyLimitNotReached} (the hard per-day cap) and {@link #computeBulkSignupWarning} (the soft
293	     * warning threshold) so both express the same per-day count in one place.
294	     *
295	     * @param registrationDate the adjusted business-day registration date to count owners for
296	     * @return the number of existing owners registered on that day
297	     */
298	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
299	        return this.clinicService.findAllOwners().stream()
300	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
301	            .count();
302	    }
303	
304	    /**
305	     * Determines whether creating an owner for the given adjusted business-day registration date should carry a bulk
306	     * signup warning. The warning is raised once more than 80 owners already carry that {@code registrationDate},
307	     * i.e. this create is at least the 82nd for the day. Evaluated before the new owner is saved, so the count
308	     * reflects only owners that predate it.
309	     *
310	     * @param registrationDate the adjusted business-day registration date of the owner being created
311	     * @return {@code true} when more than 80 owners already exist for that day, {@code false} otherwise
312	     */
313	    private boolean computeBulkSignupWarning(LocalDate registrationDate) {
314	        return countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
315	    }
316	
317	    /**
318	     * Counts how many existing owners already share the given owner's first and last name, compared
319	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
320	     * create; it is zero when the owner's name is unique.
321	     *
322	     * @param owner the newly mapped owner about to be saved
323	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
324	     */
325	    private int countNamesakes(Owner owner) {
326	        String firstName = owner.getFirstName();
327	        String lastName = owner.getLastName();
328	        return (int) this.clinicService.findAllOwners().stream()
329	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
330	                && lastName.equalsIgnoreCase(existing.getLastName()))
331	            .count();
332	    }
333	
334	    /**
335	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
336	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
337	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
338	     *
339	     * @param ownerFieldsDto the owner payload to validate
340	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
341	     */
342	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
343	        List<String> missingFields = new ArrayList<>();
344	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
345	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
346	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
347	        requireText(missingFields, "city", ownerFieldsDto.getCity());
348	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
349	        if (!missingFields.isEmpty()) {
350	            throw new MissingOwnerFieldsException(missingFields);
351	        }
352	    }
353	
354	    private void requireText(List<String> missingFields, String fieldName, String value) {
355	        if (value == null || value.isBlank()) {
356	            missingFields.add(fieldName);
357	        }
358	    }
359	
360	    /**
361	     * Validates an owner's optional {@code postcode} against its city's region. The postcode is validated only when
362	     * present; an owner created without one is accepted. Its 4-digit shape is already enforced by Bean Validation, so
363	     * this check only applies the region rule: when the city belongs to a known region (Sydney-&gt;NSW,
364	     * Melbourne-&gt;VIC, Brisbane-&gt;QLD) the postcode must fall within that region's inclusive range (NSW 2000-2099,
365	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
366	     *
367	     * @param ownerFieldsDto the incoming owner payload
368	     * @throws InvalidPostcodeException if a supplied postcode is out of range for its city's region
369	     */
370	    private void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
371	        String postcode = ownerFieldsDto.getPostcode();
372	        if (postcode == null) {
373	            return;
374	        }
375	        Region region = Region.forCity(ownerFieldsDto.getCity());
376	        if (region != null && !region.acceptsPostcode(Integer.parseInt(postcode))) {
377	            throw new InvalidPostcodeException(
378	                "postcode " + postcode + " is not valid for the city's region " + region.name());
379	        }
380	    }
381	
382	    /**
383	     * Rejects creating an owner whose whole derived {@code identityKey} (see
384	     * {@link IdentityKeyResolver#deriveIdentityKey}) equals that of an existing owner, so an owner is an identity
385	     * duplicate only when its normalized telephone, email and {@code householdId} all match another owner's. It runs
386	     * after the household id has been assigned, so the key reflects the household the owner belongs to. Owners that
387	     * share only their household (same last name and postcode, different telephone) are not caught here but by the
388	     * separate household-duplicate guard (see {@link #requireHouseholdNotDuplicate}).
389	     *
390	     * @param owner the newly mapped owner about to be saved, with its household id already assigned
391	     * @throws DuplicateOwnerException if any existing owner already has the same identity key
392	     */
393	    private void requireUniqueIdentity(Owner owner) {
394	        String identityKey = identityKeyResolver.deriveIdentityKey(owner);
395	        boolean inUse = this.clinicService.findAllOwners().stream()
396	            .anyMatch(existing -> identityKey.equals(identityKeyResolver.deriveIdentityKey(existing)));
397	        if (inUse) {
398	            throw new DuplicateOwnerException("an owner with the same identity key already exists");
399	        }
400	    }
401	
402	    /**
403	     * Flags a newly created owner as a possible (soft) duplicate. The owner has already cleared both the hard-duplicate
404	     * guard (see {@link #requireUniqueIdentity}) and the household-duplicate guard (see
405	     * {@link #requireHouseholdNotDuplicate}), so it is still being created; this only records a warning. A declared
406	     * household member (one created with {@code sharesHousehold} set to {@code true}) is never flagged: it deliberately
407	     * shares its household's last name and postcode, so it is not a suspected duplicate. Otherwise it is a possible
408	     * duplicate when some existing owner shares its last name (compared case-insensitively) and its postcode but
409	     * carries a different telephone. When such an owner is found, {@code possibleDuplicate} is set to {@code true} and
410	     * {@code possibleDuplicateOf} to that existing owner's id (the first match in
411	     * {@link ClinicService#findAllOwners()} order); otherwise {@code possibleDuplicate} is {@code false} and
412	     * {@code possibleDuplicateOf} is left null. An owner created without a postcode can never soft-match.
413	     *
414	     * @param owner          the newly mapped owner about to be saved, with its normalized fields already in place
415	     * @param ownerFieldsDto the incoming owner payload
416	     */
417	    private void flagPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
418	        owner.setPossibleDuplicate(false);
419	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
420	            return;
421	        }
422	        String postcode = owner.getPostcode();
423	        if (postcode == null || postcode.isBlank()) {
424	            return;
425	        }
426	        String lastName = owner.getLastName();
427	        String telephone = owner.getTelephone();
428	        for (Owner existing : this.clinicService.findAllOwners()) {
429	            if (lastName.equalsIgnoreCase(existing.getLastName())
430	                && postcode.equals(existing.getPostcode())
431	                && !java.util.Objects.equals(telephone, existing.getTelephone())) {
432	                owner.setPossibleDuplicate(true);
433	                owner.setPossibleDuplicateOf(existing.getId());
434	                return;
435	            }
436	        }
437	    }
438	
439	    /**
440	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
441	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
442	     *
443	     * @param city the city of the owner being created
444	     * @throws OwnerCityFullException if the city already contains 50 or more owners
445	     */
446	    private void requireCityHasCapacity(String city) {
447	        long cityOwners = this.clinicService.findAllOwners().stream()
448	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
449	            .count();
450	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
451	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
452	        }
453	    }
454	
455	    /**
456	     * Assigns the shared {@code householdId} for a newly mapped owner. The identifier is derived deterministically from
457	     * the owner's last name and postcode (see {@link HouseholdResolver#deriveHouseholdId}), so every owner sharing
458	     * those two fields resolves to the same stable value automatically, regardless of creation order and without any
459	     * explicit linking. An owner created without a postcode has no household and keeps a {@code null} identifier, so
460	     * such owners never match one another as a household.
461	     *
462	     * @param owner the newly mapped owner about to be saved
463	     */
464	    private void assignHouseholdId(Owner owner) {
465	        String postcode = owner.getPostcode();
466	        if (postcode == null || postcode.isBlank()) {
467	            owner.setHouseholdId(null);
468	            return;
469	        }
470	        owner.setHouseholdId(householdResolver.deriveHouseholdId(owner.getLastName(), postcode));
471	    }
472	
473	    /**
474	     * Rejects creating an owner that would join an existing household it has not declared. Because the household is
475	     * keyed on the last name and postcode (see {@link #assignHouseholdId}), any existing owner carrying the same
476	     * derived {@code householdId} is a member of the same household. A second such owner is a household duplicate and is
477	     * rejected, unless the payload sets {@code sharesHousehold} to {@code true}, which declares the owner a genuine
478	     * household member and lets the create proceed. An owner with no household ({@code null} householdId, i.e. created
479	     * without a postcode) can never be a household duplicate.
480	     *
481	     * @param owner          the newly mapped owner about to be saved, with its household id already assigned
482	     * @param ownerFieldsDto the incoming owner payload
483	     * @throws DuplicateOwnerException if an existing owner already belongs to this household and the create did not
484	     *                                 declare {@code sharesHousehold}
485	     */
486	    private void requireHouseholdNotDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
487	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
488	            return;
489	        }
490	        String householdId = owner.getHouseholdId();
491	        if (householdId == null) {
492	            return;
493	        }
494	        boolean sharedByExisting = this.clinicService.findAllOwners().stream()
495	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
496	        if (sharedByExisting) {
497	            throw new DuplicateOwnerException("an owner in the same household already exists");
498	        }
499	    }
500	
501	    /**
502	     * Populates the owner's transient {@code householdMemberCount} with the number of owners that belong to its
503	     * household, i.e. those sharing the same non-null {@code householdId} (including the owner itself). An owner with no
504	     * household is counted as a household of one.
505	     *
506	     * @param owner the owner whose household size should be resolved
507	     */
508	    private void populateHouseholdMemberCount(Owner owner) {
509	        String householdId = owner.getHouseholdId();
510	        if (householdId == null) {
511	            owner.setHouseholdMemberCount(1);
512	            return;
513	        }
514	        long members = this.clinicService.findAllOwners().stream()
515	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
516	            .count();
517	        owner.setHouseholdMemberCount((int) members);
518	    }
519	
520	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
521	    @Override
522	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
523	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
524	        if (currentOwner == null) {
525	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
526	        }
527	        validatePostcode(ownerFieldsDto);
528	        currentOwner.setAddress(ownerFieldsDto.getAddress());
529	        currentOwner.setCity(ownerFieldsDto.getCity());
530	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
531	        currentOwner.setLastName(ownerFieldsDto.getLastName());
532	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
533	        currentOwner.setPostcode(ownerFieldsDto.getPostcode());
534	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
535	        this.clinicService.saveOwner(currentOwner);
536	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
537	    }
538	
539	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
540	    @Transactional
541	    @Override
542	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
543	        Owner owner = this.clinicService.findOwnerById(ownerId);
544	        if (owner == null) {
545	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
546	        }
547	        this.clinicService.deleteOwner(owner);
548	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
549	    }
550	
551	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
552	    @Override
553	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
554	        Owner owner = this.clinicService.findOwnerById(ownerId);
555	        if (owner == null) {
556	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
557	        }
558	        HttpHeaders headers = new HttpHeaders();
559	        Pet pet = petMapper.toPet(petFieldsDto);
560	        owner.setId(ownerId);
561	        pet.setOwner(owner);
562	        pet.getType().setName(null);
563	        this.clinicService.savePet(pet);
564	        PetDto petDto = petMapper.toPetDto(pet);
565	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
566	            .buildAndExpand(pet.getId()).toUri());
567	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
568	    }
569	
570	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
571	    @Override
572	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
573	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
574	        if (currentOwner != null) {
575	            Pet currentPet = this.clinicService.findPetById(petId);
576	            if (currentPet != null) {
577	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
578	                currentPet.setName(petFieldsDto.getName());
579	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
580	                this.clinicService.savePet(currentPet);
581	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
582	            }
583	        }
584	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
585	    }
586	
587	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
588	    @Override
589	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
590	        HttpHeaders headers = new HttpHeaders();
591	        Visit visit = visitMapper.toVisit(visitFieldsDto);
592	        Pet pet = new Pet();
593	        pet.setId(petId);
594	        visit.setPet(pet);
595	        this.clinicService.saveVisit(visit);
596	        VisitDto visitDto = visitMapper.toVisitDto(visit);
597	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
598	            .buildAndExpand(visit.getId()).toUri());
599	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
600	    }
601	
602	
603	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
604	    @Override
605	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
606	        Owner owner = this.clinicService.findOwnerById(ownerId);
607	        if (owner != null) {
608	            Pet pet = owner.getPet(petId);
609	            if (pet != null) {
610	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
611	            }
612	        }
613	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
614	    }
615	}
